    # find largest connected component (object)
    seen=set(); best=[]
    for o in objs:
        if o in seen: continue
        st=[o]; comp=[]
        while st:
            p=st.pop()
            if p in seen: continue
            seen.add(p); comp.append(p)
            r,c=p
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                q=(r+dr,c+dc)
                if q in objs and q not in seen: st.append(q)
        if len(comp)>len(best): best=comp
    objset=set(best)
    strays=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=bg and (r,c) not in objset]
    out=[r[:] for r in g]
    for r,c in objset:
        cands=[]
        for sr,sc,v in strays:
            for dr,dc in ((0,1),(0,-1),(1,0),(-1,0)):
                rr,cc=r+dr,c+dc; d=1; ok=True
                while True:
                    if (rr,cc)==(sr,sc):
                        cands.append((d,v)); break
                    if not(0<=rr<H and 0<=cc<W): ok=False; break
                    if (rr,cc) in objset: ok=False; break
                    rr+=dr; cc+=dc; d+=1
                if ok and (rr,cc)==(sr,sc): cands.append((d,v))
        if cands:
            cands.sort(key=lambda t:(t[0],-t[1]))
            out[r][c]=cands[0][1] if mode=='min' else cands[-1][1]
    return out
